import { z } from "zod";
import { baseDocFields, zodObjectId } from "./shared";

export const organizationStatusValues = ["lead", "active", "former"] as const;

export const organizationSchema = z.object({
  ...baseDocFields,
  domains: z.array(z.string().min(1)).default([]),
  industry: z.string().min(1).optional(),
  name: z.string().min(1),
  status: z.enum(organizationStatusValues),
});
export type Organization = z.infer<typeof organizationSchema>;

export const personSchema = z.object({
  ...baseDocFields,
  emails: z.array(z.email()).default([]),
  name: z.string().min(1),
  organizationId: zodObjectId.optional(),
  role: z.string().min(1).optional(),
});
export type Person = z.infer<typeof personSchema>;

export const engagementStatusValues = [
  "planned",
  "active",
  "completed",
  "cancelled",
] as const;

export const engagementSchema = z.object({
  ...baseDocFields,
  endDate: z.date().optional(),
  organizationId: zodObjectId,
  startDate: z.date().optional(),
  status: z.enum(engagementStatusValues),
  title: z.string().min(1),
  type: z.string().min(1),
});
export type Engagement = z.infer<typeof engagementSchema>;

import { z } from "zod";
import { baseDocFields, zodObjectId } from "./shared";

export const factCategoryValues = [
  "preference",
  "objection",
  "decision-process",
  "relationship",
  "logistics",
  "background",
  "other",
] as const;
export type FactCategory = (typeof factCategoryValues)[number];

export const factAnchorsSchema = z
  .object({
    engagementId: zodObjectId.optional(),
    organizationId: zodObjectId.optional(),
    personId: zodObjectId.optional(),
  })
  .refine(
    (anchors) =>
      Boolean(
        anchors.organizationId || anchors.personId || anchors.engagementId
      ),
    { message: "A fact must be anchored to at least one entity" }
  );
export type FactAnchors = z.infer<typeof factAnchorsSchema>;

export const factSchema = z.object({
  ...baseDocFields,
  anchors: factAnchorsSchema,
  category: z.enum(factCategoryValues),
  confidence: z.number().min(0).max(1),
  confirmedBy: z.string().min(1),
  // Stubbed for later semantic search (EU embedding provider).
  embedding: z.array(z.number()).optional(),
  sourceId: zodObjectId,
  supersededBy: zodObjectId.optional(),
  text: z.string().min(1),
  // Lifecycle (dream cycle): a fact is currently valid iff BOTH are absent.
  validUntil: z.date().optional(),
});
export type Fact = z.infer<typeof factSchema>;

import { z } from "zod";
import { baseDocFields } from "./shared";

export const sourceStatusValues = [
  "received",
  "transcribed",
  "extracting",
  "proposed",
  "reviewed",
  "failed",
] as const;

export const sourceSchema = z.object({
  ...baseDocFields,
  audio: z
    .object({
      blobUrl: z.url(),
      contentType: z.string().min(1),
      durationSeconds: z.number().positive().optional(),
    })
    .optional(),
  capturedBy: z.string().min(1),
  // The textual payload: transcript (voice), body (email), or pasted text (manual).
  content: z.string().optional(),
  email: z
    .object({
      forwardedBy: z.string().min(1),
      gmailMessageId: z.string().min(1),
      originalSender: z.string().min(1),
      sentAt: z.date(),
      subject: z.string(),
    })
    .optional(),
  error: z.string().optional(),
  status: z.enum(sourceStatusValues),
  type: z.enum(["voice", "email", "manual"]),
});
export type Source = z.infer<typeof sourceSchema>;

import { z } from "zod";
import { factCategoryValues } from "./facts";
import { baseDocFields, zodObjectId } from "./shared";

export const entityDraftSchema = z.object({
  // Loose by design: extractor output. Validated against the strict entity
  // schemas at confirmation time, when the review queue materializes entities.
  data: z.record(z.string(), z.unknown()),
  draftId: z.string().min(1),
  entityType: z.enum(["organization", "person", "engagement"]),
  resolution: z
    .object({
      createdEntityId: zodObjectId.optional(),
      status: z.enum(["pending", "confirmed", "discarded"]),
    })
    .default({ status: "pending" }),
});
export type EntityDraft = z.infer<typeof entityDraftSchema>;

export const factDraftAnchorsSchema = z
  .object({
    engagementDraftId: z.string().optional(),
    engagementId: zodObjectId.optional(),
    organizationDraftId: z.string().optional(),
    organizationId: zodObjectId.optional(),
    personDraftId: z.string().optional(),
    personId: zodObjectId.optional(),
  })
  .refine((a) => Object.values(a).some(Boolean), {
    message:
      "A fact draft must anchor to an existing entity or a sibling draft",
  });

export const factDraftSchema = z.object({
  anchors: factDraftAnchorsSchema,
  category: z.enum(factCategoryValues),
  confidence: z.number().min(0).max(1),
  resolution: z
    .object({
      factId: zodObjectId.optional(),
      finalText: z.string().optional(),
      status: z.enum(["pending", "confirmed", "edited", "discarded"]),
    })
    .default({ status: "pending" }),
  text: z.string().min(1),
});
export type FactDraft = z.infer<typeof factDraftSchema>;

export const proposalSchema = z.object({
  ...baseDocFields,
  entityDrafts: z.array(entityDraftSchema),
  factDrafts: z.array(factDraftSchema),
  kind: z.enum(["ingestion", "consolidation"]),
  resolvedAt: z.date().optional(),
  resolvedBy: z.string().optional(),
  sourceId: zodObjectId.optional(),
  status: z.enum(["open", "resolved"]),
});
export type Proposal = z.infer<typeof proposalSchema>;

