import { describe, expect, test } from "bun:test";

describe("package barrel", () => {
  // The barrel is the package's canonical entry (package.json "main"). It must
  // be importable from any server runtime — Next.js, the eve agent app, and
  // Bun tests — so it must not transitively import `server-only`, which throws
  // outside a react-server bundling context. DB bootstrapping lives behind the
  // `@repo/knowledge/client` subpath instead.
  test("is importable outside a react-server environment", async () => {
    const barrel = await import("../index");
    expect(typeof barrel.buildFactsSearchPipeline).toBe("function");
    expect(typeof barrel.erasePerson).toBe("function");
    expect(typeof barrel.getCollections).toBe("function");
  });

  test("re-exports ObjectId so consumers do not import the driver directly", async () => {
    const barrel = await import("../index");
    expect(typeof barrel.ObjectId).toBe("function");
    expect(new barrel.ObjectId().toHexString()).toHaveLength(24);
  });
});

